#include <memory>
#include <iostream>

std::auto_ptr<int> factory() {
    return std::auto_ptr<int>(new int(100)); // Ownership transfer (rvalue)
}

int main() {
    std::auto_ptr<int> p1(new int(50));

    std::auto_ptr<int> p2 = p1; 
    // DESTRUCTIVE COPY: p2 now owns 50. p1 is set to null.

    if (!p1.get()) {
        std::cout << "p1 is null after assignment." << std::endl;
    }

    std::auto_ptr<int> p3 = factory();
    // Ownership transferred from temporary object returned by factory.

    std::cout << "p3 owns: " << *p3 << std::endl;
}
